SELECT notice_id, field_id, code FROM notice_codes WHERE notice_id IN (19394896, 19395679, 20297583, 20297584, 20297585, 20297586, 20297587, 20297588, 20297589, 20297590, 20297591, 20297592, 20297593, 20297594, 20298305) AND +field_id IN ('TED-FORM', 'TED-TD_DOCUMENT_TYPE') ORDER BY notice_id, section_id, field_id, ordinal LIMIT 100
